{
  "queries": [
    {
      "doc_id": "ECN-2026-029",
      "query": "Please provide the current revision history and approval signatures for ECN-2026-029. Also attach any test evidence or commissioning reports that verify the induction billet heater #1 changes performed as noted."
    },
    {
      "doc_id": "QS-CFW-4516-94",
      "query": "Confirm the latest effective date and change log for QS-CFW-4516-94. I need the documented acceptance criteria and inspection checkpoints used for 1045 connecting rods, plus records of any nonconformances against this spec in the past 12 months."
    },
    {
      "doc_id": "SOP-P1-L3-02",
      "query": "I need the approved procedure and sign-off matrix for product changeover on the Machining line (SOP-P1-L3-02). Provide evidence that operators received training on the latest version and any recent deviation reports."
    },
    {
      "doc_id": "SOP-P3-L4-04",
      "query": "Please produce the documented shift handover checklist for the Heat Treat line in SOP-P3-L4-04 and the records showing consistent use for the last quarter. If there were revisions, include rationale and approval."
    },
    {
      "doc_id": "ECN-2026-038",
      "query": "For ECN-2026-038, supply the full change description, risk assessment, and final approval trail. Include evidence that the induction billet heater #1 modification met functional testing and safety verification before return to service."
    },
    {
      "doc_id": "SOP-P2-L4-04",
      "query": "Requesting the latest revision and training records for SOP-P2-L4-04 (Shift handover - Heat Treat line). Also provide any audit findings or corrective actions tied to this SOP in the last two internal audits."
    },
    {
      "doc_id": "SOP-P1-L3-04",
      "query": "Provide the shift handover procedure for the Machining line (SOP-P1-L3-04) and examples of completed handover logs from each shift for the most recent production week. Note any deviations and their dispositions."
    },
    {
      "doc_id": "ECN-2026-014",
      "query": "For ECN-2026-014, please provide the change justification, engineering drawings before/after, and evidence of hydraulic forging press #2 validation. Include the name and signature of the approving authority and any open action items."
    },
    {
      "doc_id": "QS-CFW-4068-79",
      "query": "Confirm the acceptance criteria and measurement methods listed in QS-CFW-4068-79 for 52100 bearing rings. Provide recent inspection sample records that demonstrate compliance and any OOS results with corrective actions."
    },
    {
      "doc_id": "SOP-P1-L4-05",
      "query": "Please upload the planned shutdown procedure SOP-P1-L4-05 for the Heat Treat line, including the pre-shutdown checklist and post-startup verification steps. Attach the most recent planned shutdown report with lessons learned."
    },
    {
      "doc_id": "ECN-2026-031",
      "query": "I need the complete package for ECN-2026-031: change details, risk assessment, and commissioning evidence for Ring Rolling heat treat furnace #2. Were any material spec or process controls updated as part of this ECN?"
    },
    {
      "doc_id": "SOP-P3-L1-01",
      "query": "Provide the line startup procedure SOP-P3-L1-01 for the Hot Forge line and the training matrix showing who is authorized to perform startups. Include any recent incident reports related to startup and their corrective actions."
    },
    {
      "doc_id": "ECN-2026-007",
      "query": "For ECN-2026-007, please supply the rationale, test results, and approval record for changes to Heat Treat hydraulic forging press #2. Also indicate whether this ECN supersedes or duplicates ECN-2026-014 and explain differences."
    },
    {
      "doc_id": "QS-CFW-4919-21",
      "query": "Requesting the current spec and dimensional tolerances in QS-CFW-4919-21 for connecting rods (1045). Provide traceability requirements and any sample inspection reports that support compliance."
    },
    {
      "doc_id": "QS-CFW-3043-62",
      "query": "Please confirm material and heat treatment requirements stated in QS-CFW-3043-62 for flange blanks (4140). Attach recent metallurgical reports or hardness charts that verify adherence to this spec."
    },
    {
      "doc_id": "ECN-2026-015",
      "query": "For ECN-2026-015: provide change description, safety risk assessment, and evidence of performance testing for Heat Treat furnace #3 following the change. Include list of parts affected and any customer notifications."
    },
    {
      "doc_id": "QS-CFW-6476-89",
      "query": "Supply the inspection plan and critical characteristics listed in QS-CFW-6476-89 for bearing ring CFW-6476-89 (52100). Provide recent SPC charts or inspection summaries showing control of those characteristics."
    },
    {
      "doc_id": "ECN-2026-028",
      "query": "Please provide the scope, approvals, and validation records for ECN-2026-028 affecting Ring Rolling heat treat furnace #2. If there were follow-up corrective actions, include their closure evidence."
    },
    {
      "doc_id": "ECN-2026-020",
      "query": "For ECN-2026-020, send the engineering change package, including test protocols and evidence that Heat Treat furnace #2 meets the intended thermal profile after the change. Also identify who performed final acceptance."
    },
    {
      "doc_id": "ECN-2026-040",
      "query": "Requesting the change documentation, safety review, and post-change performance data for ECN-2026-040 (Hot Forge radial ring rolling mill #1). Were there any process control updates or operator retraining requirements tied to this ECN?"
    }
  ]
}
